/* LT / RT — V6 recording-matched analog trigger animation
   Dark paddles are always visible. The bright layer opacity is controlled
   continuously by Gamepad Viewer from the real trigger pressure. */
.xbox.edit .triggers{
    position:absolute!important;
    left:0!important;
    top:0!important;
    width:750px!important;
    height:630px!important;
    z-index:48!important;
    visibility:visible!important;
}
.xbox.edit .triggers::before,
.xbox.edit .triggers::after{
    content:""!important;
    position:absolute!important;
    display:block!important;
    z-index:0!important;
    pointer-events:none!important;
}
.xbox.edit .triggers::before{
    left:184px!important;top:37px!important;
    width:76px!important;height:107px!important;
    background:url("data:image/png;base64,") center/76px 107px no-repeat!important;
}
.xbox.edit .triggers::after{
    left:490px!important;top:37px!important;
    width:76px!important;height:107px!important;
    background:url("data:image/png;base64,") center/76px 107px no-repeat!important;
}

.xbox.edit .trigger{
    position:absolute!important;
    float:none!important;
    width:76px!important;
    height:107px!important;
    z-index:1!important;
    background-repeat:no-repeat!important;
    background-position:center!important;
    background-size:76px 107px!important;

    /*
      IMPORTANT:
      opacity is deliberately NOT !important.
      Gamepad Viewer writes the real LT/RT analog value inline,
      producing the same fade from dark -> bright seen in the recording.
    */
    opacity:0;
}
.xbox.edit .trigger.left{
    left:184px!important;top:37px!important;
    background-image:url("data:image/png;base64,")!important;
    transform:none!important;
}
.xbox.edit .trigger.right{
    left:490px!important;top:37px!important;
    right:auto!important;
    background-image:url("data:image/png;base64,")!important;
    transform:none!important;
}

